<script setup lang="ts">import{onMounted,ref}from'vue';import http from'../api/http';const rows=ref<any[]>([]);async function load(){const{data}=await http.get('/mdm/boms',{params:{page:1,size:50}});rows.value=data.data.content}async function submit(r:any){await http.post(`/mdm/boms/${r.id}/submit`);load()}onMounted(load)</script><template><section><div class="toolbar"><div><h1 class="page-title">BOM 版本中心</h1><p class="page-subtitle">工程与制造共用的权威 BOM；审批发布后才替换生产计划正在使用的当前版本</p></div><el-button @click="load">刷新版本</el-button></div><el-card><div class="version-banner"><div class="version-icon">V</div><div><b>版本治理已启用</b><span>BOM 子件只能引用已发布物料，ERP/MES 始终消费当前有效版本。</span></div></div><el-table :data="rows" stripe><el-table-column prop="bomCode" label="BOM 编码" min-width="130"/><el-table-column prop="bomName" label="BOM 名称" min-width="190"/><el-table-column prop="productCode" label="产品编码"/><el-table-column prop="bomType" label="类型"><template #default="{row}"><el-tag effect="plain">{{row.bomType}}</el-tag></template></el-table-column><el-table-column prop="bomVersion" label="版本"/><el-table-column prop="status" label="状态"><template #default="{row}"><el-tag :type="row.status==='PUBLISHED'?'success':row.status==='PENDING'?'warning':'info'">{{row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button v-if="row.status==='DRAFT'||row.status==='REJECTED'" type="primary" link @click="submit(row)">提交审批</el-button></template></el-table-column></el-table></el-card></section></template><style scoped>.version-banner{display:flex;align-items:center;gap:12px;margin-bottom:16px;padding:13px 15px;border-radius:10px;background:linear-gradient(90deg,#f2f7ff,#fafcff)}.version-icon{display:grid;place-items:center;width:36px;height:36px;border-radius:10px;background:#3776df;color:#fff;font-weight:800}.version-banner b,.version-banner span{display:block}.version-banner b{font-size:13px;color:#31557e}.version-banner span{margin-top:4px;font-size:12px;color:#7d91aa}</style>
